import { useMemo, useState, type ReactNode } from 'react'
import { useNavigate, useSearchParams } from 'react-router-dom'
import type { ReviewState } from '../../../app/fixtureSession'
import type { ScreenDefinition, ScreenRole } from '../../../app/screenManifest'
import { Badge, Button, Field, inputCls, PageHeader, Table, Td, Th } from '../../../components/ui'
import { ActionDialog, EmptyState, FilterBar, InlineMessage, LoadingState, SummaryStrip, WorkSection } from '../../../components/workspace'
import { seedPens } from '../../../data/pensData'
import { loadRationStore, nextRationCode, rationAtDate, recordFeedingSession, recordFeedingSessionsBatch, reviseFeedingSession, saveRation, transitionRation } from '../rationStore'
import { HERD_GROUPS, type FeedRation, type FeedSessionLine, type FeedingSession } from '../feedStore'

const hcmDay = (value = new Date()) => new Intl.DateTimeFormat('en-CA', { timeZone: 'Asia/Ho_Chi_Minh', year: 'numeric', month: '2-digit', day: '2-digit' }).format(value)
const day = () => hcmDay()
const tomorrow = () => hcmDay(new Date(Date.now() + 86400000))
const pens = seedPens.filter((pen) => pen.status === 'ACTIVE')
const sessions: FeedingSession[] = ['MORNING', 'AFTERNOON', 'EVENING']
const sessionName: Record<FeedingSession, string> = { MORNING: 'Sáng', AFTERNOON: 'Chiều', EVENING: 'Tối' }
const sessionTime: Record<FeedingSession, string> = { MORNING: '06:30', AFTERNOON: '16:30', EVENING: '20:00' }
const labelRole = (role: ScreenRole) => ({ owner: 'Chủ trại', manager: 'Quản lý', technician: 'Kỹ thuật viên', guest: 'Khách', cs: 'CS', pm: 'PM', sa: 'SA' }[role] || role)
const amount = (value: number) => `${Math.round(value).toLocaleString('vi-VN')} đ`
const rationStatusLabel: Record<string, string> = { DRAFT: 'Nháp', SCHEDULED: 'Sắp áp dụng', EFFECTIVE: 'Đang hiệu lực', ENDED: 'Đã kết thúc', CANCELLED: 'Đã hủy', POSTED: 'Đã ghi sổ', VOIDED: 'Đã hủy' }
const herdGroupLabel: Record<string, string> = { 'Finishing bull': 'Bò đực vỗ béo', 'Breeding cow': 'Bò cái sinh sản', Calf: 'Bê', Other: 'Khác' }

function Frame({ screen, role, actions, children }: { screen: ScreenDefinition; role: ScreenRole; actions?: ReactNode; children: ReactNode }) { return <div className="flex w-full flex-col gap-6"><PageHeader title={screen.viTitle} sub={`Vai trò ${labelRole(role)} · quản lý khẩu phần và lần cho ăn`}>{actions}</PageHeader>{children}</div> }
function State({ state, children }: { state: ReviewState; children: ReactNode }) { if (state === 'loading') return <LoadingState label="Đang tải dữ liệu khẩu phần…" />; if (state === 'error') return <InlineMessage tone="err">Không thể tải dữ liệu thức ăn.</InlineMessage>; if (state === 'empty') return <EmptyState title="Chưa có dữ liệu khẩu phần" description="Tạo khẩu phần hoặc lần cho ăn đầu tiên để bắt đầu." />; return <>{children}</> }
function Denied({ role, allowed }: { role: ScreenRole; allowed: ScreenRole[] }) { return <InlineMessage tone="err" title="Không có quyền">{labelRole(role)} không được phép. Vai trò hợp lệ: {allowed.map(labelRole).join(', ')}.</InlineMessage> }
function ReadOnly({ role, state }: { role: ScreenRole; state: ReviewState }) { return role === 'technician' || state === 'read-only' ? <InlineMessage tone="info">Chỉ đọc: thao tác ghi khẩu phần và kho đã bị khóa.</InlineMessage> : null }
function tone(status: string) { return status === 'EFFECTIVE' || status === 'POSTED' ? 'ok' as const : status === 'VOIDED' || status === 'ENDED' || status === 'CANCELLED' ? 'err' as const : 'warn' as const }

function blank(store: ReturnType<typeof loadRationStore>, id?: string): FeedRation { const found = store.rations.find((row) => row.id === id); return found || { id: `ration-${Date.now()}`, code: nextRationCode(store.rations), name: '', version: 1, herdGroup: 'Other', penIds: [], penNames: [], headcount: 0, sessions: [{ type: 'MORNING', time: sessionTime.MORNING }, { type: 'AFTERNOON', time: sessionTime.AFTERNOON }], components: [], effectiveFrom: tomorrow(), effectiveTo: '', basis: '', status: 'DRAFT', history: [], updatedAt: new Date().toISOString() } }

function List({ screen, role, state }: { screen: ScreenDefinition; role: ScreenRole; state: ReviewState }) {
  if (role !== 'owner' && role !== 'manager') return <Frame screen={screen} role={role}><Denied role={role} allowed={['owner', 'manager']} /></Frame>
  const nav = useNavigate(); const store = loadRationStore(); const [, refresh] = useState(0); const [query, setQuery] = useState(''); const [status, setStatus] = useState('ACTIVE'); const canWrite = (role === 'owner' || role === 'manager') && state !== 'read-only'; const [action, setAction] = useState<{ type: 'stop' | 'cancel'; row: FeedRation } | null>(null); const [stopDate, setStopDate] = useState(tomorrow); const [reason, setReason] = useState(''); const [actionError, setActionError] = useState(''); const rows = store.rations.filter((row) => (status === 'ALL' || status === 'ACTIVE' ? status === 'ALL' || row.status === 'EFFECTIVE' || row.status === 'SCHEDULED' : row.status === status) && (!query || `${row.code} ${row.name}`.toLowerCase().includes(query.toLowerCase()))); const effective = store.rations.filter((row) => row.status === 'EFFECTIVE'); const mutate = (fn: () => void) => { try { fn(); refresh((value) => value + 1); closeAction() } catch (error) { setActionError(error instanceof Error ? error.message : 'Không thể cập nhật.') } }; const openAction = (next: { type: 'stop' | 'cancel'; row: FeedRation }) => { setAction(next); setReason(''); setActionError(''); setStopDate(tomorrow()) }; const closeAction = () => { setAction(null); setReason(''); setActionError('') }; const submitAction = () => { const trimmed = reason.trim(); if (!trimmed) { setActionError('Nhập lý do để tiếp tục.'); return } if (!action) return; if (action.type === 'stop' && !/^\d{4}-\d{2}-\d{2}$/.test(stopDate)) { setActionError('Ngày dừng phải có dạng YYYY-MM-DD.'); return } mutate(() => transitionRation(action.row.id, action.type === 'stop' ? 'STOP' : 'CANCEL', trimmed, action.row.version, action.type === 'stop' ? stopDate : undefined)) }; const coveredHeads = effective.reduce((sum, row) => sum + row.headcount, 0); const dailyKg = effective.reduce((sum, row) => sum + row.headcount * row.components.reduce((total, component) => total + component.kgPerHead.reduce((a, value) => a + value, 0), 0), 0); const dailyCost = effective.reduce((sum, row) => sum + row.headcount * row.components.reduce((total, component) => total + component.kgPerHead.reduce((a, value) => a + value, 0) * (store.stock.find((item) => item.id === component.feedId)?.averageCost || 0), 0), 0); const perHeadKg = coveredHeads ? dailyKg / coveredHeads : 0; const perHeadCost = coveredHeads ? dailyCost / coveredHeads : 0
  return <Frame screen={screen} role={role} actions={canWrite && <Button variant="primary" onClick={() => nav('/ui/scr-116')}>+ Tạo khẩu phần</Button>}><State state={state}><ReadOnly role={role} state={state} /><FilterBar><Field label="Tìm mã / tên"><input className={inputCls} value={query} onChange={(event) => setQuery(event.target.value)} /></Field><Field label="Trạng thái"><select className={inputCls} value={status} onChange={(event) => setStatus(event.target.value)}><option value="ACTIVE">Hiệu lực / sắp áp dụng</option><option value="EFFECTIVE">Đang hiệu lực</option><option value="SCHEDULED">Sắp áp dụng</option><option value="ENDED">Đã kết thúc</option><option value="CANCELLED">Đã hủy</option><option value="ALL">Tất cả</option></select></Field></FilterBar><SummaryStrip items={[{ label: 'Khẩu phần hiệu lực', value: effective.length }, { label: 'Đầu bò/ngày', value: coveredHeads }, { label: 'Kế hoạch kg/ngày', value: `${dailyKg.toFixed(2)} kg` }, { label: 'Kế hoạch kg/đầu/ngày', value: `${perHeadKg.toFixed(2)} kg` }, { label: 'Chi phí đ/ngày', value: amount(dailyCost) }, { label: 'Chi phí đ/đầu/ngày', value: amount(perHeadCost) }, { label: 'Chuồng chưa có khẩu phần', value: pens.filter((pen) => !effective.some((row) => row.penIds.includes(pen.code))).length }, { label: 'Phiên bản', value: store.rations.length }, { label: 'Dữ liệu cập nhật', value: 'Theo thời gian thực' }]} /><WorkSection title="Danh sách phiên bản"><Table wide scroll><thead><tr><Th>Mã / tên / version</Th><Th>Chuồng</Th><Th>Đầu</Th><Th>Thành phần · kg/đầu/ngày · chi phí · ngày tồn</Th><Th>Hiệu lực</Th><Th>Trạng thái</Th><Th /></tr></thead><tbody>{rows.map((row) => <tr key={row.id}><Td><strong>{row.code} · {row.name}</strong><div className="text-[11px] text-muted">v{row.version}</div></Td><Td>{row.penNames.join(', ')}</Td><Td>{row.headcount}</Td><Td>{row.components.map((component) => { const kg = component.kgPerHead.reduce((sum, value) => sum + value, 0); const cost = kg * (store.stock.find((item) => item.id === component.feedId)?.averageCost || 0); const days = row.headcount * kg ? (store.stock.find((item) => item.id === component.feedId)?.stockKg || 0) / (row.headcount * kg) : 0; return <div key={component.feedId}>{component.feedCode || component.feedName}: {kg.toFixed(2)} kg/đầu/ngày · {Math.round(cost).toLocaleString('vi-VN')} đ/đầu/ngày · {days.toFixed(1)} ngày{days < 3 && <span className="text-warn-fg"> · sắp thiếu</span>}</div> })}</Td><Td>{row.effectiveFrom}{row.effectiveTo ? ` → ${row.effectiveTo}` : ''}</Td><Td><Badge tone={tone(row.status)}>{rationStatusLabel[row.status] || row.status}</Badge></Td><Td>{canWrite && <div className="flex gap-1"><Button small onClick={() => nav(`/ui/scr-116?id=${row.id}`)}>Sửa / phiên bản mới</Button>{row.status === 'SCHEDULED' && <Button small onClick={() => openAction({ type: 'cancel', row })}>Hủy</Button>}{row.status === 'EFFECTIVE' && <Button small onClick={() => openAction({ type: 'stop', row })}>Dừng từ ngày…</Button>}</div>}</Td></tr>)}</tbody></Table>{!rows.length && <EmptyState compact title="Chưa có khẩu phần phù hợp" description="Đổi bộ lọc hoặc tạo phiên bản mới." />}</WorkSection></State><ActionDialog open={Boolean(action)} title={action?.type === "stop" ? "Dừng khẩu phần" : "Hủy khẩu phần"} description={action?.type === "stop" ? "Chọn ngày dừng và nhập lý do." : "Nhập lý do hủy để lưu dấu vết phiên bản."} error={actionError} confirmLabel={action?.type === "stop" ? "Xác nhận dừng" : "Xác nhận hủy"} confirmTone="danger" onCancel={closeAction} onConfirm={submitAction}>{action?.type === "stop" && <Field label="Ngày dừng *"><input autoFocus type="date" min={tomorrow()} className={inputCls} value={stopDate} onChange={(event) => { setStopDate(event.target.value); setActionError("") }} /></Field>}<Field label="Lý do *"><textarea autoFocus={action?.type !== "stop"} className={`${inputCls} mt-3 min-h-24`} maxLength={500} value={reason} onChange={(event) => { setReason(event.target.value); setActionError("") }} placeholder="Ví dụ: thay đổi kế hoạch cho ăn." /></Field></ActionDialog></Frame>
}

function Editor({ screen, role, state }: { screen: ScreenDefinition; role: ScreenRole; state: ReviewState }) {
  if (role !== 'owner' && role !== 'manager') return <Frame screen={screen} role={role}><Denied role={role} allowed={['owner', 'manager']} /></Frame>
  const nav = useNavigate(); const [params] = useSearchParams(); const store = loadRationStore(); const original = blank(store, params.get('id') || undefined); const immutable = ['EFFECTIVE', 'ENDED', 'CANCELLED'].includes(original.status); const initial = immutable ? { ...original, sourceId: original.id, id: original.id, version: original.version + 1, status: 'DRAFT' as const, effectiveFrom: tomorrow(), effectiveTo: '' } : original; const [draft, setDraft] = useState(initial); const [error, setError] = useState(''); const writable = state !== 'read-only'; const feeds = store.stock.filter((item) => item.status === 'ACTIVE'); const patch = (value: Partial<FeedRation>) => setDraft((old) => ({ ...old, ...value })); const updateSessions = (value: FeedRation['sessions']) => setDraft((old) => ({ ...old, sessions: value, components: old.components.map((component) => ({ ...component, kgPerHead: value.map((_, index) => Number(component.kgPerHead[index] || 0)) })) })); const selectPen = (id: string) => setDraft((old) => { const ids = old.penIds.includes(id) ? old.penIds.filter((value) => value !== id) : [...old.penIds, id]; return { ...old, penIds: ids, penNames: ids.map((value) => pens.find((pen) => pen.code === value)?.name || value), headcount: ids.reduce((sum, value) => sum + (pens.find((pen) => pen.code === value)?.count || 0), 0) } }); const previous = immutable ? store.rations.find((row) => row.code === original.code && row.version === original.version - 1) : undefined; const draftKgPerHead = draft.components.reduce((sum, component) => sum + component.kgPerHead.reduce((total, value) => total + value, 0), 0); const draftCostPerHead = draft.components.reduce((sum, component) => sum + component.kgPerHead.reduce((total, value) => total + value, 0) * (feeds.find((item) => item.id === component.feedId)?.averageCost || 0), 0); const previousKgPerHead = previous?.components.reduce((sum, component) => sum + component.kgPerHead.reduce((total, value) => total + value, 0), 0) || 0; const previousCostPerHead = previous?.components.reduce((sum, component) => sum + component.kgPerHead.reduce((total, value) => total + value, 0) * (feeds.find((item) => item.id === component.feedId)?.averageCost || 0), 0) || 0; const kgDelta = draftKgPerHead - previousKgPerHead; const costDelta = draftCostPerHead - previousCostPerHead; const save = () => { try { saveRation(draft, store.rations.some((row) => row.id === original.id) ? original.version : undefined); nav('/ui/scr-115') } catch (cause) { setError(cause instanceof Error ? cause.message : 'Không thể lưu.') } }
  return <Frame screen={screen} role={role} actions={<><Button onClick={() => nav('/ui/scr-115')}>Hủy</Button>{writable && <Button variant="primary" onClick={save}>Lưu khẩu phần</Button>}</>}><State state={state}><ReadOnly role={role} state={state} />{immutable && <InlineMessage tone="info">Đang tạo phiên bản mới; phiên bản trước được giữ nguyên và sẽ kết thúc trước ngày bắt đầu mới. {previous ? `So với v${previous.version}: ${previous.headcount} → ${draft.headcount} đầu · ${draftKgPerHead.toFixed(2)} kg/đầu/ngày (${kgDelta >= 0 ? '+' : ''}${kgDelta.toFixed(2)}) · ${amount(draftCostPerHead)} (${costDelta >= 0 ? '+' : ''}${amount(costDelta)}).` : `Tổng bản nháp: ${draft.headcount} đầu · ${draftKgPerHead.toFixed(2)} kg/đầu/ngày · ${amount(draftCostPerHead)}.`}</InlineMessage>}{error && <InlineMessage tone="err">{error}</InlineMessage>}<WorkSection title="Thông tin phiên bản"><div className="grid gap-4 md:grid-cols-2 xl:grid-cols-4"><Field label="Mã"><input className={inputCls} readOnly value={draft.code} /></Field><Field label="Tên khẩu phần *"><input className={inputCls} maxLength={100} disabled={!writable} value={draft.name} onChange={(event) => patch({ name: event.target.value })} /></Field><Field label="Nhóm đàn"><select className={inputCls} disabled={!writable} value={draft.herdGroup} onChange={(event) => patch({ herdGroup: event.target.value })}>{HERD_GROUPS.map((group) => <option key={group} value={group}>{herdGroupLabel[group] || group}</option>)}</select></Field><Field label="Hiệu lực từ *"><input type="date" min={tomorrow()} className={inputCls} disabled={!writable} value={draft.effectiveFrom} onChange={(event) => patch({ effectiveFrom: event.target.value })} /></Field><Field label="Đến ngày"><input type="date" min={draft.effectiveFrom} className={inputCls} disabled={!writable} value={draft.effectiveTo} onChange={(event) => patch({ effectiveTo: event.target.value })} /></Field><Field label="Cơ sở / ghi chú"><input className={inputCls} maxLength={500} disabled={!writable} value={draft.basis} onChange={(event) => patch({ basis: event.target.value })} /></Field></div></WorkSection><WorkSection title="Chuồng áp dụng"><div className="grid gap-2 sm:grid-cols-2 lg:grid-cols-3">{pens.map((pen) => <label key={pen.code} className="flex gap-2 border-b border-rule py-2 text-xs"><input type="checkbox" disabled={!writable} checked={draft.penIds.includes(pen.code)} onChange={() => selectPen(pen.code)} /><span>{pen.code} · {pen.name}<br /><span className="text-muted">{pen.count}/{pen.capacity} đầu · {pen.stage}</span></span></label>)}</div><p className="m-0 mt-3 text-xs">Tổng đầu bò: <strong>{draft.headcount}</strong></p></WorkSection><WorkSection title="Cữ và định lượng"><div className="mb-4 flex flex-wrap items-center gap-3">{sessions.map((type) => { const active = draft.sessions.some((row) => row.type === type); return <label key={type} className="inline-flex min-w-fit items-center gap-2 whitespace-nowrap text-xs"><input type="checkbox" disabled={!writable} checked={active} onChange={() => updateSessions(active ? draft.sessions.filter((row) => row.type !== type) : [...draft.sessions, { type, time: sessionTime[type] }])} />{sessionName[type]}<input type="time" className={`${inputCls} w-auto`} value={draft.sessions.find((row) => row.type === type)?.time || sessionTime[type]} disabled={!writable || !active} onChange={(event) => updateSessions(draft.sessions.map((row) => row.type === type ? { ...row, time: event.target.value } : row))} /></label> })}</div><Table wide scroll><thead><tr><Th>Mặt hàng đang hoạt động</Th>{draft.sessions.map((row) => <Th key={row.type}>{sessionName[row.type]} kg/đầu</Th>)}<Th>Chi phí/đầu/ngày</Th><Th /></tr></thead><tbody>{draft.components.map((component, index) => <tr key={`${component.feedId}-${index}`}><Td><select className={inputCls} disabled={!writable} value={component.feedId} onChange={(event) => { const next = feeds.find((item) => item.id === event.target.value); setDraft((old) => ({ ...old, components: old.components.map((row, rowIndex) => rowIndex === index ? { ...row, feedId: event.target.value, feedCode: next?.code || '', feedName: next?.name || '' } : row) })) }}>{feeds.map((item) => <option key={item.id} value={item.id}>{item.code} · {item.name}</option>)}</select></Td>{draft.sessions.map((row, sessionIndex) => <Td key={row.type}><input type="number" min="0" step="0.01" className={inputCls} disabled={!writable} value={component.kgPerHead[sessionIndex] || 0} onChange={(event) => setDraft((old) => ({ ...old, components: old.components.map((item, rowIndex) => rowIndex === index ? { ...item, kgPerHead: item.kgPerHead.map((value, valueIndex) => valueIndex === sessionIndex ? Number(event.target.value) : value) } : item) }))} /></Td>)}<Td>{amount(component.kgPerHead.reduce((sum, value) => sum + value, 0) * (feeds.find((item) => item.id === component.feedId)?.averageCost || 0))}</Td><Td>{writable && <Button small onClick={() => setDraft((old) => ({ ...old, components: old.components.filter((_, rowIndex) => rowIndex !== index) }))}>Xóa</Button>}</Td></tr>)}</tbody><tfoot><tr className="font-semibold"><Td>Tổng kg/đầu/ngày</Td>{draft.sessions.map((row) => <Td key={row.type}>{draft.components.reduce((sum, component) => sum + (component.kgPerHead[draft.sessions.findIndex((entry) => entry.type === row.type)] || 0), 0).toFixed(2)}</Td>)}<Td>{amount(draftCostPerHead)}</Td><Td /></tr></tfoot></Table><div className="mt-3 grid gap-2 md:grid-cols-2">{draft.components.map((component) => { const kg = component.kgPerHead.reduce((sum, value) => sum + value, 0); const item = feeds.find((feed) => feed.id === component.feedId); const days = draft.headcount * kg ? (item?.stockKg || 0) / (draft.headcount * kg) : 0; return <InlineMessage key={component.feedId} tone={days < 3 ? 'warn' : 'info'}>{component.feedCode || component.feedName}: {kg.toFixed(2)} kg/đầu/ngày · {days.toFixed(1)} ngày tồn{days < 3 ? ' · sắp thiếu' : ''}</InlineMessage> })}</div>{writable && <Button small onClick={() => setDraft((old) => ({ ...old, components: [...old.components, { feedId: feeds[0]?.id || '', feedCode: feeds[0]?.code || '', feedName: feeds[0]?.name || '', kgPerHead: old.sessions.map(() => 0.1) }] }))}>+ Thêm mặt hàng</Button>}{!draft.components.length && <EmptyState compact title="Chưa có mặt hàng" description="Thêm ít nhất một mặt hàng đang hoạt động." />}</WorkSection></State></Frame>
}

function planLines(ration: FeedRation | undefined, session: FeedingSession, headcount: number): FeedSessionLine[] { if (!ration || !ration.sessions.some((row) => row.type === session)) return []; const index = ration.sessions.findIndex((row) => row.type === session); return ration.components.map((component) => ({ feedId: component.feedId, feedCode: component.feedCode, feedName: component.feedName, plannedKg: (component.kgPerHead[index] || 0) * headcount, actualKg: 0 })) }
type EntrySlotDraft = { raw: string; date: string; penId: string; penName: string; session: FeedingSession; headcount: number; ration?: FeedRation; existing?: ReturnType<typeof loadRationStore>['feedings'][number]; lines: FeedSessionLine[]; outside: boolean; time: string; leftover: string; note: string; invalidReason?: string }

function Log({ screen, role, state }: { screen: ScreenDefinition; role: ScreenRole; state: ReviewState }) {
  const nav = useNavigate(); const [params] = useSearchParams(); const store = loadRationStore(); const [date, setDate] = useState(params.get('date') || day()); const [week, setWeek] = useState(false); const [pen, setPen] = useState(params.get('penId') || 'ALL'); const [session, setSession] = useState(params.get('session') || 'ALL'); const [selectedSlots, setSelectedSlots] = useState<string[]>([]); const [selectionError, setSelectionError] = useState(''); const canWrite = role === 'manager' && state !== 'read-only'; const dates = Array.from({ length: week ? 7 : 1 }, (_, index) => { const [year, month, calendarDate] = date.split('-').map(Number); const value = new Date(Date.UTC(year, month - 1, calendarDate + index, 12)); return new Intl.DateTimeFormat('en-CA', { timeZone: 'Asia/Ho_Chi_Minh', year: 'numeric', month: '2-digit', day: '2-digit' }).format(value) }); const actualRows = store.feedings.filter((row) => dates.includes(row.date) && row.status === 'POSTED' && (pen === 'ALL' || row.penId === pen) && (session === 'ALL' || row.session === session)); const expected = dates.flatMap((selectedDate) => pens.filter((item) => pen === 'ALL' || item.code === pen).flatMap((item) => { const ration = rationAtDate(store, item.code, selectedDate); return (ration?.sessions || []).filter((entry) => session === 'ALL' || entry.type === session).map((entry) => ({ date: selectedDate, penId: item.code, penName: item.name, headcount: item.count, session: entry.type, ration, plan: planLines(ration, entry.type, item.count), actual: actualRows.find((row) => row.date === selectedDate && row.penId === item.code && row.session === entry.type) })) })); const rows = expected.length ? expected : actualRows.map((actual) => ({ date: actual.date, penId: actual.penId, penName: actual.penName, headcount: actual.headcount, session: actual.session, ration: undefined, plan: actual.lines.map((line) => ({ ...line, plannedKg: line.plannedKg, actualKg: 0 })), actual })); const missing = expected.filter((row) => !row.actual).length; const consumption = actualRows.reduce<Record<string, number>>((total, row) => { row.lines.forEach((line) => { total[line.feedCode] = (total[line.feedCode] || 0) + line.actualKg }); return total }, {}); const low = store.stock.filter((item) => item.status === 'ACTIVE' && item.stockKg <= item.minimumKg); const plannedKg = rows.reduce((sum, row) => sum + row.plan.reduce((total, line) => total + line.plannedKg, 0), 0); const actualKg = actualRows.reduce((sum, row) => sum + row.lines.reduce((total, line) => total + line.actualKg, 0), 0); const variancePct = plannedKg ? ((actualKg - plannedKg) / plannedKg) * 100 : 0; const stockDeducted = actualRows.reduce((sum, row) => sum + row.lines.reduce((total, line) => total + line.actualKg * (store.stock.find((item) => item.id === line.feedId)?.averageCost || 0), 0), 0); const contextQuery = new URLSearchParams({ date, ...(pen !== 'ALL' ? { penId: pen } : {}), ...(session !== 'ALL' ? { session } : {}) }).toString()
  return <Frame screen={screen} role={role} actions={canWrite && <><Button onClick={() => { if (!selectedSlots.length) { setSelectionError('Chọn ít nhất một cữ chưa ghi để điền nhanh.'); return } setSelectionError(''); nav(`/ui/scr-118?bulk=1&slotIds=${encodeURIComponent(selectedSlots.join(','))}&fill=1`) }}>Điền nhanh theo kế hoạch</Button><Button variant="primary" onClick={() => nav(`/ui/scr-118?${contextQuery}`)}>+ Ghi cữ</Button></>}><State state={state}><ReadOnly role={role} state={state} />{selectionError && <InlineMessage tone="warn" title="Chưa thể điền nhanh">{selectionError}</InlineMessage>}<FilterBar><Field label="Ngày bắt đầu"><input type="date" max={day()} className={inputCls} value={date} onChange={(event) => setDate(event.target.value)} /></Field><Field label="Phạm vi"><select className={inputCls} value={week ? 'WEEK' : 'DAY'} onChange={(event) => setWeek(event.target.value === 'WEEK')}><option value="DAY">Ngày</option><option value="WEEK">7 ngày</option></select></Field><Field label="Chuồng"><select className={inputCls} value={pen} onChange={(event) => setPen(event.target.value)}><option value="ALL">Tất cả</option>{pens.map((item) => <option key={item.code}>{item.code}</option>)}</select></Field><Field label="Cữ"><select className={inputCls} value={session} onChange={(event) => setSession(event.target.value)}><option value="ALL">Tất cả</option>{sessions.map((item) => <option key={item}>{sessionName[item]}</option>)}</select></Field></FilterBar><SummaryStrip items={[{ label: 'Kế hoạch', value: `${plannedKg.toFixed(1)} kg` }, { label: 'Thực tế', value: `${actualKg.toFixed(1)} kg` }, { label: 'Chênh lệch', value: `${(actualKg - plannedKg).toFixed(1)} kg` }, { label: 'Tỷ lệ sai lệch', value: `${variancePct.toFixed(1)}%` }, { label: 'Kho đã trừ', value: amount(stockDeducted) }, { label: 'Cữ chưa ghi', value: missing }]} /><WorkSection title="Nhật ký cho ăn"><Table wide scroll><thead><tr><Th>Ngày · chuồng</Th><Th>Cữ</Th><Th>Khẩu phần</Th><Th>Kế hoạch → thực tế</Th><Th>Giờ / người ghi</Th><Th>Trạng thái</Th><Th /></tr></thead><tbody>{rows.map((row) => { const actual = row.actual; const plan = row.plan.reduce((sum, line) => sum + line.plannedKg, 0); const consumed = actual?.lines.reduce((sum, line) => sum + line.actualKg, 0) || 0; return <tr key={`${row.date}-${row.penId}-${row.session}`}><Td>{row.date} · {row.penName}<div className="text-[11px] text-muted">{row.headcount} đầu</div></Td><Td>{sessionName[row.session]}</Td><Td>{row.ration?.code || 'Ngoài khẩu phần'}</Td><Td>{plan.toFixed(1)} → {consumed.toFixed(1)} kg</Td><Td>{actual ? `${actual.feedingTime} · ${actual.fedBy}` : '—'}</Td><Td><Badge tone={actual ? 'ok' : 'warn'}>{actual ? 'Đã ghi' : 'Chưa ghi'}</Badge></Td><Td>{canWrite && !actual && <label className="flex items-center gap-1 text-xs"><input type="checkbox" checked={selectedSlots.includes(`${row.date}:${row.penId}:${row.session}`)} onChange={() => setSelectedSlots((current) => current.includes(`${row.date}:${row.penId}:${row.session}`) ? current.filter((slot) => slot !== `${row.date}:${row.penId}:${row.session}`) : [...current, `${row.date}:${row.penId}:${row.session}`])} />Chọn</label>}{canWrite && actual && <Button small onClick={() => nav(`/ui/scr-119?id=${actual.id}`)}>Sửa / hủy</Button>}</Td></tr> })}</tbody><tfoot><tr className="font-semibold"><Td colSpan={3}>Tổng ngày / kỳ</Td><Td>{plannedKg.toFixed(1)} → {actualKg.toFixed(1)} kg</Td><Td colSpan={3}>Sai lệch {variancePct.toFixed(1)}% · {missing} cữ chưa ghi</Td></tr></tfoot></Table>{!rows.length && <EmptyState compact title="Chưa có cữ theo bộ lọc" description="Đổi ngày hoặc cấu hình khẩu phần." />}</WorkSection><WorkSection title="Tiêu thụ theo mặt hàng"><Table wide><thead><tr><Th>Mặt hàng</Th><Th>Thực tế</Th><Th>Tồn còn lại</Th><Th>Chi phí</Th><Th>Trạng thái</Th></tr></thead><tbody>{Object.entries(consumption).map(([code, kg]) => { const item = store.stock.find((row) => row.code === code); const remaining = item?.stockKg || 0; return <tr key={code}><Td>{code} · {item?.name || 'Không xác định'}</Td><Td>{kg.toFixed(1)} kg</Td><Td>{remaining.toFixed(1)} kg</Td><Td>{amount(kg * (item?.averageCost || 0))}</Td><Td><Badge tone={remaining <= (item?.minimumKg || 0) ? 'warn' : 'ok'}>{remaining <= 0 ? 'Hết hàng' : remaining <= (item?.minimumKg || 0) ? 'Sắp hết' : 'Đủ'}</Badge></Td></tr>})}{!Object.keys(consumption).length && <tr><Td colSpan={4}>Chưa có lượng sử dụng trong kỳ.</Td></tr>}</tbody></Table></WorkSection><div className="flex items-center justify-between gap-3"><InlineMessage tone={low.length ? 'warn' : 'ok'}>{low.length ? `Tồn kho thấp hoặc đã hết: ${low.map((item) => item.code).join(', ')}.` : 'REM-10: chưa có mặt hàng dưới mức tối thiểu.'}</InlineMessage>{low.length > 0 && <Button small onClick={() => nav('/ui/scr-113')}>Mở kho để xử lý</Button>}</div></State></Frame>
}

function Entry({ screen, role, state }: { screen: ScreenDefinition; role: ScreenRole; state: ReviewState }) {
  const [params] = useSearchParams()
  return params.get('bulk') === '1' ? <BulkEntry screen={screen} role={role} state={state} /> : <SingleOrBulkEntry screen={screen} role={role} state={state} />
}

function BulkEntry({ screen, role, state }: { screen: ScreenDefinition; role: ScreenRole; state: ReviewState }) {
  if (role !== 'manager') return <Frame screen={screen} role={role}><Denied role={role} allowed={['manager']} /></Frame>
  const nav = useNavigate(); const [params] = useSearchParams(); const store = loadRationStore(); const writable = state !== 'read-only'; const fill = params.get('fill') === '1'; const slotIds = (params.get('slotIds') || '').split(',').map((value) => value.trim()).filter(Boolean)
  const [slotRows, setSlotRows] = useState<EntrySlotDraft[]>(() => {
    const rows = slotIds.map((raw) => {
      const [date, penId, sessionValue] = raw.split(':'); const sessionValid = sessions.includes(sessionValue as FeedingSession); const targetPen = pens.find((item) => item.code === penId); const validDate = /^\d{4}-\d{2}-\d{2}$/.test(date || '')
      const targetRation = validDate && targetPen && sessionValid ? rationAtDate(store, penId, date) : undefined; const existing = validDate && targetPen && sessionValid ? store.feedings.find((row) => row.date === date && row.penId === penId && row.session === sessionValue && row.status === 'POSTED') : undefined
      const invalidReason = !validDate ? 'Ngày slot không hợp lệ.' : !targetPen ? 'Chuồng không tồn tại hoặc không ACTIVE.' : !sessionValid ? 'Cữ không hợp lệ.' : date > day() ? 'Ngày cho ăn không được ở tương lai.' : undefined
      return { raw, date: date || '', penId: penId || '', session: (sessionValid ? sessionValue : 'MORNING') as FeedingSession, penName: targetPen?.name || penId || '—', headcount: targetPen?.count || 0, ration: targetRation, existing, outside: !targetRation, lines: targetRation ? planLines(targetRation, sessionValue as FeedingSession, targetPen?.count || 0).map((line) => fill ? { ...line, actualKg: line.plannedKg } : line) : [], time: targetRation?.sessions.find((entry) => entry.type === sessionValue)?.time || sessionTime[(sessionValid ? sessionValue : 'MORNING') as FeedingSession], leftover: '', note: '', invalidReason }
    })
    const counts = new Map(rows.map((row) => [`${row.date}:${row.penId}:${row.session}`, 0])); rows.forEach((row) => { const key = `${row.date}:${row.penId}:${row.session}`; counts.set(key, (counts.get(key) || 0) + 1) })
    return rows.map((row) => { const key = `${row.date}:${row.penId}:${row.session}`; return counts.get(key)! > 1 ? { ...row, invalidReason: 'Trùng slot ngày · chuồng · cữ.' } : row })
  })
  const [reviewBulk, setReviewBulk] = useState(false); const [fedBy, setFedBy] = useState('Nguyễn Văn Hùng'); const [error, setError] = useState('')
  const patchSlot = (index: number, patch: Partial<EntrySlotDraft>) => setSlotRows((rows) => rows.map((row, rowIndex) => rowIndex === index ? { ...row, ...patch } : row))
  const patchLine = (slotIndex: number, lineIndex: number, actualKg: number) => setSlotRows((rows) => rows.map((row, rowIndex) => rowIndex === slotIndex ? { ...row, lines: row.lines.map((line, index) => index === lineIndex ? { ...line, actualKg } : line) } : row))
  const addFeed = (slotIndex: number) => setSlotRows((rows) => rows.map((row, rowIndex) => { if (rowIndex !== slotIndex) return row; const next = store.stock.find((item) => item.status === 'ACTIVE' && !row.lines.some((line) => line.feedId === item.id)); return next ? { ...row, lines: [...row.lines, { feedId: next.id, feedCode: next.code, feedName: next.name, plannedKg: 0, actualKg: 0 }] } : row }))
  const fillPlan = (slotIndex: number) => setSlotRows((rows) => rows.map((row, rowIndex) => rowIndex === slotIndex && row.ration ? { ...row, outside: false, lines: planLines(row.ration, row.session, row.headcount).map((line) => ({ ...line, actualKg: line.plannedKg })) } : row))
  const validate = () => {
    if (!slotRows.length) return 'Cần chọn ít nhất một slot chưa ghi.'
    const fresh = loadRationStore(); const keys = new Set<string>()
    for (const row of slotRows) {
      const key = `${row.date}:${row.penId}:${row.session}`; if (row.invalidReason) return `${row.raw}: ${row.invalidReason}`; if (keys.has(key)) return `${key}: trùng slot.`; keys.add(key)
      const existing = fresh.feedings.find((item) => item.date === row.date && item.penId === row.penId && item.session === row.session && item.status === 'POSTED'); if (existing) return `${key}: đã có bản ghi, không thể ghi đè.`
      if (!row.outside && !row.ration) return `${key}: chưa có khẩu phần theo ngày.`
      if (!row.lines.length) return `${key}: cần ít nhất một dòng thức ăn.`
      if (row.lines.some((line) => !Number.isFinite(line.actualKg) || line.actualKg < 0)) return `${key}: lượng thực tế không hợp lệ.`
      if (row.lines.reduce((sum, line) => sum + line.actualKg, 0) <= 0) return `${key}: tổng lượng thực tế phải lớn hơn 0.`
      if (row.leftover !== '' && (!Number.isFinite(Number(row.leftover)) || Number(row.leftover) < 0)) return `${key}: thức ăn thừa không hợp lệ.`
    }
    return ''
  }
  const save = () => { const validationError = validate(); if (validationError) { setError(validationError); return } if (!reviewBulk) { setReviewBulk(true); return } try { const entries = slotRows.map((row, index) => ({ id: `feeding-${Date.now()}-${index}`, date: row.date, penId: row.penId, penName: row.penName, headcount: row.headcount, rationId: row.outside ? undefined : row.ration?.id, rationCode: row.outside ? undefined : row.ration?.code, rationVersion: row.outside ? undefined : row.ration?.version, session: row.session, feedingTime: row.time, fedBy, lines: row.lines, leftoverKg: row.leftover === '' ? undefined : Number(row.leftover), note: row.note, status: 'POSTED' as const, history: ['Tạo bản ghi'], version: 1, updatedAt: new Date().toISOString() })); recordFeedingSessionsBatch(entries); nav('/ui/scr-117') } catch (cause) { setError(cause instanceof Error ? cause.message : 'Không thể ghi các cữ.') } }
  return <Frame screen={screen} role={role} actions={<><Button onClick={() => nav('/ui/scr-117')}>Hủy</Button>{writable && <Button variant="primary" onClick={save}>{reviewBulk ? `Xác nhận ghi ${slotRows.length} cữ` : 'Xem lại và ghi các cữ'}</Button>}</>}><State state={state}><ReadOnly role={role} state={state} />{error && <InlineMessage tone="err" title="Không thể ghi các cữ">{error}</InlineMessage>}<WorkSection title={`Các cữ đã chọn (${slotRows.length})`} description="Ngày, chuồng, cữ và nguồn khẩu phần được khóa theo từng cữ; chỉ lượng thực tế được nhập riêng cho từng cữ."><div className="mb-4 max-w-sm"><Field label="Người cho ăn *"><select className={inputCls} value={fedBy} disabled={!writable} onChange={(event) => setFedBy(event.target.value)}><option>Nguyễn Văn Hùng</option><option>Phạm Thị Hoa</option><option>Trần Minh Đức</option></select></Field></div>{slotRows.map((row, slotIndex) => { const total = row.lines.reduce((sum, line) => sum + line.actualKg, 0); const existing = row.existing || loadRationStore().feedings.find((item) => item.date === row.date && item.penId === row.penId && item.session === row.session && item.status === 'POSTED'); return <div key={`${row.raw}-${slotIndex}`} className="border-t border-rule py-4"><div className="flex flex-wrap items-start justify-between gap-3"><div><strong>{row.date || '—'} · {row.penId || '—'} · {sessionName[row.session]}</strong><div className="mt-1 text-xs text-subtle">Chuồng: {row.penName} · Khẩu phần: {row.ration ? `${row.ration.code} · v${row.ration.version}` : 'Ngoài khẩu phần'} · Giờ kế hoạch: {row.time}</div></div><Badge tone={row.invalidReason || existing ? 'err' : row.outside ? 'warn' : 'ok'}>{row.invalidReason || (existing ? 'Đã có bản ghi' : row.outside ? 'Ngoài khẩu phần' : 'Sẵn sàng')}</Badge></div>{row.invalidReason && <InlineMessage className="mt-3" tone="err">{row.invalidReason}</InlineMessage>}{existing && !row.invalidReason && <InlineMessage className="mt-3" tone="err">Cữ này đã có bản ghi đã ghi sổ; hãy bỏ khỏi danh sách đã chọn.</InlineMessage>}<div className="mt-3 flex flex-wrap gap-2">{writable && row.ration && <Button small onClick={() => fillPlan(slotIndex)}>Điền theo kế hoạch</Button>}{writable && <Button small onClick={() => addFeed(slotIndex)}>+ Thêm thức ăn</Button>}<label className="flex items-center gap-2 text-xs"><input type="checkbox" checked={row.outside} disabled={!writable} onChange={(event) => patchSlot(slotIndex, { outside: event.target.checked, lines: event.target.checked ? [] : row.ration ? planLines(row.ration, row.session, row.headcount) : [] })} />Ghi thức ăn ngoài khẩu phần cho slot này</label></div><Table wide scroll><thead><tr><Th>Mặt hàng</Th><Th>Kế hoạch</Th><Th>Thực tế *</Th><Th>Tồn</Th></tr></thead><tbody>{row.lines.map((line, lineIndex) => <tr key={line.feedId}><Td>{line.feedCode} · {line.feedName}</Td><Td>{line.plannedKg.toFixed(2)} kg</Td><Td><input aria-label={`${row.raw} · ${line.feedCode} thực tế`} type="number" min="0" step="0.01" className={inputCls} value={line.actualKg} disabled={!writable} onChange={(event) => patchLine(slotIndex, lineIndex, Number(event.target.value))} /></Td><Td>{store.stock.find((item) => item.id === line.feedId)?.stockKg.toFixed(1) || '0'} kg</Td></tr>)}</tbody></Table>{!row.lines.length && <EmptyState compact title="Chưa có dòng thức ăn" description="Điền theo khẩu phần hoặc thêm mặt hàng đang hoạt động." />}<div className="mt-3 grid gap-3 md:grid-cols-3"><div className="text-xs"><strong>Tổng thực tế</strong><div className="mt-1 text-lg font-semibold">{total.toFixed(2)} kg</div></div><Field label="Thức ăn thừa (kg)"><input type="number" min="0" step="0.01" className={inputCls} value={row.leftover} disabled={!writable} onChange={(event) => patchSlot(slotIndex, { leftover: event.target.value })} /></Field><Field label="Ghi chú"><textarea className={`${inputCls} min-h-20`} maxLength={500} value={row.note} disabled={!writable} onChange={(event) => patchSlot(slotIndex, { note: event.target.value })} /></Field></div></div> })}{!slotRows.length && <EmptyState compact title="Không có cữ hợp lệ" description="Quay lại nhật ký và chọn các cữ chưa ghi." />}</WorkSection></State></Frame>
}

function SingleOrBulkEntry({ screen, role, state }: { screen: ScreenDefinition; role: ScreenRole; state: ReviewState }) {
  if (role !== 'manager') return <Frame screen={screen} role={role}><Denied role={role} allowed={['manager']} /></Frame>
  const nav = useNavigate(); const [params] = useSearchParams(); const store = loadRationStore(); const [date, setDate] = useState(params.get('date') || day()); const dateFromLog = Boolean(params.get('date')); const [penId, setPenId] = useState(params.get('penId') || pens[0]?.code || ''); const pen = pens.find((item) => item.code === penId); const [session, setSession] = useState<FeedingSession>((params.get('session') as FeedingSession) || 'MORNING'); const bulk = false; const slotIds: string[] = []; const initialSlotRows: EntrySlotDraft[] = []; const [slotRows] = useState<EntrySlotDraft[]>(initialSlotRows); const reviewSlots = slotRows; const [selectedSessions, setSelectedSessions] = useState<FeedingSession[]>([(params.get('session') as FeedingSession) || 'MORNING']); const [reviewBulk, setReviewBulk] = useState(false); const ration = rationAtDate(store, penId, date); const rationSessions = ration?.sessions.map((entry) => entry.type) || sessions; const [outside, setOutside] = useState(!ration); const [lines, setLines] = useState<FeedSessionLine[]>(planLines(ration, session, pen?.count || 0).map((line) => params.get('fill') ? { ...line, actualKg: line.plannedKg } : line)); const [time, setTime] = useState(ration?.sessions.find((entry) => entry.type === session)?.time || sessionTime[session]); const [fedBy, setFedBy] = useState('Nguyễn Văn Hùng'); const [leftover, setLeftover] = useState(''); const [note, setNote] = useState(''); const [error, setError] = useState(''); const writable = state !== 'read-only'; const total = lines.reduce((sum, line) => sum + line.actualKg, 0); const stockWarning = lines.some((line) => (store.stock.find((item) => item.id === line.feedId)?.stockKg || 0) < line.actualKg); const context = (nextPen: string, nextSession: FeedingSession, nextDate = date, isOutside = outside) => { const next = pens.find((item) => item.code === nextPen); const nextRation = rationAtDate(store, nextPen, nextDate); setLines(isOutside ? [] : planLines(nextRation, nextSession, next?.count || 0)); setTime(nextRation?.sessions.find((entry) => entry.type === nextSession)?.time || sessionTime[nextSession]) }; const save = () => { try { const entries = [{ id: `feeding-${Date.now()}`, date, penId, penName: pen?.name || penId, headcount: pen?.count || 0, rationId: outside ? undefined : ration?.id, rationCode: outside ? undefined : ration?.code, rationVersion: outside ? undefined : ration?.version, session, feedingTime: time, fedBy, lines, leftoverKg: leftover === '' ? undefined : Number(leftover), note, status: 'POSTED' as const, history: ['Tạo bản ghi'], version: 1, updatedAt: new Date().toISOString() }]; recordFeedingSession(entries[0]); nav('/ui/scr-117') } catch (cause) { setError(cause instanceof Error ? cause.message : 'Không thể ghi cữ.') } }; const addFeed = () => { const next = store.stock.find((item) => item.status === 'ACTIVE' && !lines.some((line) => line.feedId === item.id)); if (next) setLines((old) => [...old, { feedId: next.id, feedCode: next.code, feedName: next.name, plannedKg: 0, actualKg: 0 }]) }; const fillPlan = () => setLines(planLines(ration, session, pen?.count || 0).map((line) => ({ ...line, actualKg: line.plannedKg })))
  return <Frame screen={screen} role={role} actions={<><Button onClick={() => nav('/ui/scr-117')}>Hủy</Button>{writable && <Button variant="primary" onClick={save}>{bulk && !reviewBulk ? 'Xem lại và ghi các cữ' : bulk ? `Xác nhận ghi ${reviewSlots.length} cữ` : 'Lưu và trừ kho'}</Button>}</>}><State state={state}><ReadOnly role={role} state={state} />{bulk && <WorkSection title={`Các cữ đã chọn (${reviewSlots.length})`} description="Danh sách xác nhận lấy từ các cữ đã chọn; mỗi dòng giữ nguồn khẩu phần riêng."><Table wide scroll><thead><tr><Th>Ngày</Th><Th>Chuồng</Th><Th>Cữ</Th><Th>Nguồn khẩu phần</Th><Th>Trạng thái</Th></tr></thead><tbody>{reviewSlots.map((slot) => <tr key={`${slot.date}-${slot.penId}-${slot.session}`}><Td>{slot.date}</Td><Td>{slot.penId} · {slot.penName}</Td><Td>{sessionName[slot.session]}</Td><Td>{slot.ration ? `${slot.ration.code} · v${slot.ration.version}` : 'Ngoài khẩu phần'}</Td><Td>{slot.existing ? 'Đã có bản ghi' : 'Chưa ghi · sẽ tạo'}</Td></tr>)}</tbody></Table>{!reviewSlots.length && <EmptyState compact title="Không có cữ hợp lệ" description="Quay lại nhật ký và chọn các cữ chưa ghi." />}</WorkSection>}{bulk && reviewBulk && <InlineMessage tone="info">Đang xem lại {reviewSlots.length} cữ đã chọn. Kiểm tra từng chuồng, ngày, cữ và nguồn khẩu phần trước khi xác nhận.</InlineMessage>}{error && <InlineMessage tone="err">{error}</InlineMessage>}<WorkSection title="Thông tin cữ ăn"><div className="grid gap-4 md:grid-cols-2 xl:grid-cols-4"><Field label="Ngày *"><input type="date" max={day()} className={inputCls} value={date} disabled={!writable || dateFromLog} onChange={(event) => { setDate(event.target.value); context(penId, session, event.target.value) }} /></Field><Field label="Chuồng *"><select className={inputCls} value={penId} disabled={!writable} onChange={(event) => { setPenId(event.target.value); context(event.target.value, session) }}>{pens.map((item) => <option key={item.code} value={item.code}>{item.code} · {item.name}</option>)}</select></Field><Field label="Cữ *"><select className={inputCls} value={session} disabled={!writable} onChange={(event) => { const value = event.target.value as FeedingSession; setSession(value); context(penId, value) }}>{rationSessions.map((key) => <option key={key} value={key}>{sessionName[key]}</option>)}</select></Field>{bulk && <div className="flex flex-wrap items-center gap-3 text-xs"><span>Cữ cần ghi:</span>{rationSessions.map((key) => <label key={key} className="flex items-center gap-1"><input type="checkbox" checked={selectedSessions.includes(key)} disabled={!writable} onChange={() => setSelectedSessions((current) => current.includes(key) ? current.filter((value) => value !== key) : [...current, key])} />{sessionName[key]}</label>)}</div>}<Field label="Giờ thực tế *"><input type="time" className={inputCls} value={time} disabled={!writable} onChange={(event) => setTime(event.target.value)} /></Field><Field label="Người cho ăn *"><select className={inputCls} value={fedBy} disabled={!writable} onChange={(event) => setFedBy(event.target.value)}><option>Nguyễn Văn Hùng</option><option>Phạm Thị Hoa</option><option>Trần Minh Đức</option></select></Field><Field label="Khẩu phần theo ngày"><input className={inputCls} readOnly value={outside ? 'Ngoài khẩu phần' : ration ? `${ration.code} · v${ration.version}` : 'Chưa có'} /></Field></div><label className="mt-4 flex items-center gap-2 text-xs"><input type="checkbox" checked={outside} disabled={!writable} onChange={(event) => { setOutside(event.target.checked); context(penId, session, date, event.target.checked) }} />Ghi thức ăn ngoài khẩu phần</label></WorkSection><WorkSection title="Dòng thức ăn"><div className="mb-3 flex gap-2">{writable && !outside && <Button small onClick={fillPlan}>Điền theo kế hoạch</Button>}{writable && <Button small onClick={addFeed}>+ Thêm thức ăn</Button>}</div><Table wide scroll><thead><tr><Th>Mặt hàng</Th><Th>Kế hoạch</Th><Th>Thực tế *</Th><Th>Tồn</Th></tr></thead><tbody>{lines.map((line, index) => <tr key={line.feedId}><Td>{line.feedCode} · {line.feedName}</Td><Td>{line.plannedKg.toFixed(2)} kg</Td><Td><input type="number" min="0" step="0.01" className={inputCls} value={line.actualKg} disabled={!writable} onChange={(event) => setLines((old) => old.map((item, rowIndex) => rowIndex === index ? { ...item, actualKg: Number(event.target.value) } : item))} /></Td><Td>{store.stock.find((item) => item.id === line.feedId)?.stockKg.toFixed(1) || '0'} kg</Td></tr>)}</tbody></Table>{!lines.length && <EmptyState compact title="Chưa có dòng thức ăn" description="Điền theo khẩu phần hoặc thêm mặt hàng đang hoạt động." />}<div className="grid gap-4 md:grid-cols-3"><Field label="Tổng thực tế"><input className={inputCls} readOnly value={`${total.toFixed(2)} kg`} /></Field><Field label="Thức ăn thừa (kg)"><input type="number" min="0" step="0.01" className={inputCls} value={leftover} disabled={!writable} onChange={(event) => setLeftover(event.target.value)} /></Field><Field label="Ghi chú"><textarea className={`${inputCls} min-h-20`} maxLength={500} value={note} disabled={!writable} onChange={(event) => setNote(event.target.value)} /></Field></div>{stockWarning && <InlineMessage tone="warn">Một dòng vượt tồn hiện tại; không thể lưu nếu tồn kho không đủ.</InlineMessage>}</WorkSection></State></Frame>
}

function Correction({ screen, role, state }: { screen: ScreenDefinition; role: ScreenRole; state: ReviewState }) {
  if (role !== 'manager') return <Frame screen={screen} role={role}><Denied role={role} allowed={['manager']} /></Frame>
  const nav = useNavigate(); const [params] = useSearchParams(); const record = loadRationStore().feedings.find((row) => row.id === params.get('id')); const [action, setAction] = useState<'CORRECT'|'VOID'>('CORRECT'); const [lines, setLines] = useState<FeedSessionLine[]>(record?.lines || []); const [reason, setReason] = useState(''); const [error, setError] = useState(''); const [voidConfirm, setVoidConfirm] = useState(false); const writable = state !== 'read-only'; if (!record) return <Frame screen={screen} role={role}><EmptyState title="Không tìm thấy bản ghi cữ" description="Liên kết không hợp lệ; quay lại nhật ký." actionLabel="Về nhật ký" onAction={() => nav('/ui/scr-117')} /></Frame>; const save = () => { try { reviseFeedingSession(record.id, action, lines, reason, record.version); nav('/ui/scr-117') } catch (cause) { setError(cause instanceof Error ? cause.message : 'Không thể lưu revision.') } }; const before = record.lines.reduce((sum, line) => sum + line.actualKg, 0); const after = (action === 'VOID' ? 0 : lines.reduce((sum, line) => sum + line.actualKg, 0));
  return <Frame screen={screen} role={role} actions={<><Button onClick={() => nav('/ui/scr-117')}>Quay lại</Button>{writable && <Button variant="primary" onClick={action === 'VOID' ? () => setVoidConfirm(true) : save}>{action === 'VOID' ? 'Xác nhận hủy' : 'Lưu điều chỉnh'}</Button>}</>}><State state={state}><ReadOnly role={role} state={state} />{error && <InlineMessage tone="err">{error}</InlineMessage>}<WorkSection title="Bản ghi gốc"><div className="grid gap-3 md:grid-cols-4 text-xs"><div><strong>Ngày / chuồng</strong><br />{record.date} · {record.penName}</div><div><strong>Cữ / giờ</strong><br />{sessionName[record.session]} · {record.feedingTime}</div><div><strong>Người ghi</strong><br />{record.fedBy}</div><div><strong>Phân bổ lô và kho</strong><br />{Object.values(record.allocations || {}).flat().map((row) => `${row.lotNo} · ${row.warehouse}: ${row.quantityKg} kg`).join(' | ') || 'Chưa có thông tin phân bổ'}</div></div></WorkSection><WorkSection title="Sửa hoặc hủy bản ghi"><Field label="Thao tác"><select className={inputCls} value={action} disabled={!writable} onChange={(event) => setAction(event.target.value as 'CORRECT'|'VOID')}><option value="CORRECT">Sửa lượng đã ghi</option><option value="VOID">Hủy và hoàn trả lượng gốc</option></select></Field><Table wide scroll><thead><tr><Th>Mặt hàng</Th><Th>Trước</Th><Th>Sau</Th><Th>Chênh lệch kho</Th></tr></thead><tbody>{lines.map((line, index) => { const old = record.lines.find((row) => row.feedId === line.feedId)?.actualKg || 0; const next = action === 'VOID' ? 0 : line.actualKg; return <tr key={line.feedId}><Td>{line.feedCode} · {line.feedName}</Td><Td>{old.toFixed(2)} kg</Td><Td><input type="number" min="0" step="0.01" className={inputCls} value={next} disabled={!writable || action === 'VOID'} onChange={(event) => setLines((oldLines) => oldLines.map((item, rowIndex) => rowIndex === index ? { ...item, actualKg: Number(event.target.value) } : item))} /></Td><Td>{(next - old).toFixed(2)} kg</Td></tr> })}</tbody></Table><InlineMessage tone="info">{after < before ? `Sẽ hoàn trả ${(before - after).toFixed(2)} kg theo đúng lô và kho ban đầu.` : `Sẽ tiêu hao thêm ${(after - before).toFixed(2)} kg theo phân bổ mới.`}</InlineMessage><Field label="Lý do *"><textarea className={`${inputCls} min-h-24`} maxLength={500} value={reason} disabled={!writable} onChange={(event) => setReason(event.target.value)} /></Field></WorkSection><WorkSection title="Lịch sử điều chỉnh"><div className="space-y-2 text-xs">{(record.revisions || []).map((revision) => <div key={`${revision.version}-${revision.at}`} className="border-b border-rule pb-2"><strong>v{revision.version} · {revision.action}</strong> · {revision.at}<br />{revision.reason}</div>)}{!(record.revisions || []).length && <p className="m-0 text-subtle">Chưa có lần điều chỉnh.</p>}</div></WorkSection></State><ActionDialog open={voidConfirm} title="Xác nhận hủy lần cho ăn" description="Lượng đã tiêu hao sẽ được hoàn trả theo đúng lô và kho đã ghi nhận." error={error} confirmLabel="Xác nhận hủy" confirmTone="danger" onCancel={() => setVoidConfirm(false)} onConfirm={() => { setVoidConfirm(false); save() }}><InlineMessage tone="warn">Kiểm tra lại lý do và dữ liệu trước khi hoàn trả lượng gốc.</InlineMessage></ActionDialog></Frame>
}

export function RationScreen({ screen, role, state }: { screen: ScreenDefinition; role: ScreenRole; state: ReviewState }) { if (screen.id === 'SCR-115') return <List screen={screen} role={role} state={state} />; if (screen.id === 'SCR-116') return <Editor screen={screen} role={role} state={state} />; if (screen.id === 'SCR-117') return <Log screen={screen} role={role} state={state} />; if (screen.id === 'SCR-118') return <Entry screen={screen} role={role} state={state} />; return <Correction screen={screen} role={role} state={state} /> }
